learning_path:
{
  "path": [
    {
      "step": 1,
      "course_id": "EDX819",
      "rationale": "Foundational knowledge in climate science is essential for understanding the energy transition. This course provides a comprehensive introduction to climate change, its causes, and its impact on the planet."
    },
    {
      "step": 2,
      "course_id": "EDX80",
      "rationale": "Building on the foundational knowledge of climate science, this course delves into the specifics of climate change mitigation and the importance of limiting global average temperature rise to below 2°C compared to pre-industrial levels."
    },
    {
      "step": 3,
      "course_id": "EDX283",
      "rationale": "With a solid understanding of climate change and mitigation strategies, this course provides a deeper dive into the science behind climate change, including Earth's climate history, the greenhouse effect, and natural and man-made effects on climate."
    },
    {
      "step": 4,
      "course_id": "EDX1987",
      "rationale": "This course takes the learner to the next level of understanding by introducing the principles of climate modeling, allowing them to build more complicated, realistic models of the Earth's climate."
    },
    {
      "step": 5,
      "course_id": "EDX2216",
      "rationale": "With a solid grasp of climate modeling, this course focuses on designing climate-neutral industry and electricity generation, reviewing industrial sources of emissions and existing technological options to mitigate them."
    },
    {
      "step": 6,
      "course_id": "EDX838",
      "rationale": "This course provides a comprehensive overview of the living world, including ecosystems, human populations, and the impact of human activities on the environment, setting the stage for a deeper exploration of environmental science."
    },
    {
      "step": 7,
      "course_id": "EDX1026",
      "rationale": "Building on the foundational knowledge of environmental science, this course delves into the specifics of pollution and resources, including the impact of human activities on the environment and the importance of sustainable resource management."
    },
    {
      "step": 8,
      "course_id": "EDX3029",
      "rationale": "With a solid understanding of environmental science and pollution, this course provides a deeper dive into the principles of thermodynamics and hydrostatics, essential for understanding the energy transition."
    },
    {
      "step": 9,
      "course_id": "EDX838",
      "rationale": "This course takes the learner to the next level of understanding by introducing the principles of natural disasters, exploring the ongoing conflict between humans and nature, and the global impact of natural disasters."
    },
    {
      "step": 10,
      "course_id": "EDX2381",
      "rationale": "With a solid grasp of natural disasters, this course provides a comprehensive overview of the role of people in the environment, including the impact of human activities on the planet and the importance of sustainable development."
    }
  ]
}

