learning_path:
{
  "path": [
    {
      "step": 1,
      "course_id": "COU2893",
      "rationale": "Begin with foundational knowledge of teaching methods and instructional design."
    },
    {
      "step": 2,
      "course_id": "COU3488",
      "rationale": "Build on prior knowledge of teaching methods by learning about designing lesson plans and assessment plans for English language teaching."
    },
    {
      "step": 3,
      "course_id": "COU1613",
      "rationale": "Increase cognitive load by applying instructional design principles to health professions education, which requires a higher level of complexity and critical thinking."
    },
    {
      "step": 4,
      "course_id": "COU4253",
      "rationale": "Foster a growth mindset and encourage self-directed learning by applying teaching philosophy and lesson planning skills to real-world scenarios."
    },
    {
      "step": 5,
      "course_id": "COU3995",
      "rationale": "Monitor and adjust pacing to meet the needs of diverse learners by reflecting on the role of a reflective practitioner in teaching and learning."
    }
  ]
}

