{
  "path": [
    {
      "step": 1,
      "course_id": "COU5529",
      "rationale": "Foundational course on international humanitarian law, covering the basics of the subject."
    },
    {
      "step": 2,
      "course_id": "EDX2117",
      "rationale": "Builds on the foundational course, providing in-depth analysis of complex issues related to armed conflicts and international humanitarian law."
    },
    {
      "step": 3,
      "course_id": "COU1244",
      "rationale": "Applies the knowledge gained from the previous courses, providing an insider perspective into the work of international criminal courts and tribunals."
    },
    {
      "step": 4,
      "course_id": "EDX2972",
      "rationale": "Expands the understanding of human rights law, enabling learners to analyze and comment on key controversies surrounding its development."
    },
    {
      "step": 5,
      "course_id": "COU1205",
      "rationale": "Covers the fundamentals of international criminal law, providing a comprehensive understanding of the subject."
    },
    {
      "step": 6,
      "course_id": "EDX1241",
      "rationale": "Applies the knowledge gained from the previous courses, providing a deeper understanding of international law and its application."
    },
    {
      "step": 7,
      "course_id": "COU3152",
      "rationale": "Builds on the knowledge gained from the previous courses, enabling learners to understand the philosophy and logic underlying international humanitarian law norms."
    },
    {
      "step": 8,
      "course_id": "EDX3071",
      "rationale": "Applies the knowledge gained from the previous courses, providing a comprehensive understanding of international investment law and its application."
    },
    {
      "step": 9,
      "course_id": "COU5028",
      "rationale": "Covers the intersection of healthcare and human rights, providing a deeper understanding of the subject."
    },
    {
      "step": 10,
      "course_id": "EDX3232",
      "rationale": "Applies the knowledge gained from the previous courses, enabling learners to understand the complexities of global business and politics."
    }
  ]
}

