{
  "path": [
    {
      "step": 1,
      "course_id": "EDX2078",
      "rationale": "This foundational course introduces the learner to corporate sustainability, social innovation, and ethics, providing a solid understanding of the strategic challenges faced by modern organizations."
    },
    {
      "step": 2,
      "course_id": "EDX2424",
      "rationale": "Building on the foundational knowledge from the previous course, this course helps the learner adopt a critical perspective on managerial practices related to societal issues and stimulate impactful changes in organizations."
    },
    {
      "step": 3,
      "course_id": "EDX3254",
      "rationale": "This course provides the learner with the sustainability leadership skills needed to implement climate risk management and facilitate ESG integration in their organization, creating long-term value for shareholders and society."
    },
    {
      "step": 4,
      "course_id": "EDX3299",
      "rationale": "With a solid understanding of sustainability leadership, this course equips the learner with the skills to navigate complex sustainability issues and engage stakeholders in sustainability challenges and motivating for positive, long-lasting change in their organization."
    },
    {
      "step": 5,
      "course_id": "EDX3401",
      "rationale": "This course provides the learner with the insight and tools needed to leverage supply chain technology, analytics, and innovation to optimize processes and manage the risks of operating in volatile, uncertain, and complex environments to create resilient and sustainable supply chains."
    },
    {
      "step": 6,
      "course_id": "EDX3436",
      "rationale": "The learner will gain a holistic understanding of the growing business case for sustainability in the fashion industry, insight into business model theory, and the ability to move their brand from promise to purpose through a people-centric approach."
    }
  ]
}

{
  "path": [
    {
      "step": 1,
      "course_id": "EDX495",
      "rationale": "This course covers the foundational knowledge of English grammar, which is essential for academic writing."
    },
    {
      "step": 2,
      "course_id": "EDX2694",
      "rationale": "Building on the foundational knowledge of English grammar, this course provides a comprehensive introduction to academic writing, including how to write effective sentences and paragraphs, introductions, and conclusions."
    },
    {
      "step": 3,
      "course_id": "EDX61",
      "rationale": "This course focuses on the structure and organization of an argumentative essay, which is a crucial aspect of academic writing. It builds on the knowledge gained in the previous courses and provides a more advanced understanding of academic writing."
    },
    {
      "step": 4,
      "course_id": "EDX792",
      "rationale": "This course refines persuasive writing techniques and essay development, which is essential for advanced academic writing. It also provides skills for proofreading, self-editing, revision, tone, and vocabulary, which are critical for effective writing."
    }
  ]
}

